30	/** A context over real files on disk, for the live-gate tests. */
31	function diskCtx(paths) {
32	  const present = paths.filter((f) => existsSync(path.join(REPO, f)));
33	  return {
34	    present,
35	    ctx: {
36	      files: present,
37	      read: (p) => (present.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
38	    },
39	  };
40	}
41	
42	const LOOKUPS = {
43	  venues: { "33": { name: "Pleasance Courtyard" } },
44	  rooms: ["Above", "Below"],
45	  genres: ["Comedy", "Theatre"],
46	  subgenres: ["Improv", "Stand-up"],
47	  ticketStatuses: ["SOLD_OUT", "TICKETS_AVAILABLE"],
48	  ageRestrictions: ["EIGHTEEN", "SIXTEEN"],
49	};
50	
51	/** A context over an in-memory {path: object} map, matching the engine's ctx. */
52	function ctxOf(tree) {
53	  const files = Object.keys(tree);
54	  return {
55	    files,
56	    read: (p) => (p in tree ? JSON.stringify(tree[p]) : null),
57	  };
58	}
59	
60	const cleanDay = [
61	  { id: "X", title: "A show", genre: 1, subs: [0, 1], venue: "33", room: 0, ts: 1 },
62	  // -1 is the producer's "unknown" for room and ticket status (normalize.py), not
63	  // an out-of-range index — the check must stay quiet on it.
64	  { id: "Y", title: "Another", genre: 0, subs: [], venue: "33", room: -1, ts: -1 },
65	];
66	
67	test("clean day file + master produce no findings", () => {
68	  const out = rule.run(ctxOf({
69	    "data/venues.json": LOOKUPS,
70	    "data/days/2026-08-07.json": cleanDay,
71	    "data/normalized/shows.min.json": [
72	      { i: "X", t: "A show", g: 1, sg: [0], rm: 0, ar: 1, p: [{ t: 1 }] },
73	    ],
74	  }));
75	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
76	});
77	
78	test("a genre index past the end of venues.json genres is reported", () => {
79	  // The exact regression this guards: someone shrinks/reorders a lookup list (or
80	  // hand-edits a day file) and every affected card silently mislabels.
81	  const out = rule.run(ctxOf({
82	    "data/venues.json": LOOKUPS,
83	    "data/days/2026-08-07.json": [{ id: "X", title: "A show", genre: 7, venue: "33", room: 0, ts: 1 }],
84	  }));
85	  assert.equal(out.length, 1);
86	  assert.equal(out[0].rule, "edfringe-lookup-indices");
87	  assert.equal(out[0].severity, "blocking");
88	  assert.equal(out[0].file, "data/days/2026-08-07.json");
89	  assert.match(out[0].what, /genre = 7 is outside venues\.json "genres"/);
90	  assert.ok(out[0].fix.includes("normalize.py"), "the fix must name the regeneration command");
91	});
92	
93	test("out-of-range subgenre, room and ticket-status indices are reported too", () => {
94	  const out = rule.run(ctxOf({
95	    "data/venues.json": LOOKUPS,
96	    "data/days/2026-08-07.json": [
97	      { id: "X", title: "A", genre: 0, subs: [9], venue: "33", room: 0, ts: 1 },
98	      { id: "Y", title: "B", genre: 0, subs: [], venue: "33", room: 4, ts: 1 },
99	      { id: "Z", title: "C", genre: 0, subs: [], venue: "33", room: 0, ts: 5 },
100	    ],
101	  }));
102	  assert.equal(out.length, 3);
103	  assert.match(out[0].what, /subs\[\] = 9 is outside venues\.json "subgenres"/);
104	  assert.match(out[1].what, /room = 4 is outside venues\.json "rooms"/);
105	  assert.match(out[2].what, /ts = 5 is outside venues\.json "ticketStatuses"/);
106	});
107	
108	test("the master's own keys (g / rm / ar / sg / p[].t) are checked", () => {
109	  const out = rule.run(ctxOf({
110	    "data/venues.json": LOOKUPS,
111	    "data/normalized/shows.min.json": [
112	      { i: "X", t: "A show", g: 0, sg: [3], rm: 0, ar: 0, p: [{ t: 1 }] },
113	      { i: "Y", t: "Bad status", g: 0, sg: [], rm: 0, ar: 0, p: [{ t: 9 }] },
114	    ],
115	  }));
116	  assert.equal(out.length, 2);
117	  assert.ok(out.every((f) => f.file === "data/normalized/shows.min.json"));
118	  assert.match(out[0].what, /sg\[\] = 3 is outside venues\.json "subgenres"/);
119	  assert.match(out[1].what, /p\[0\]\.t = 9 is outside venues\.json "ticketStatuses"/);
120	});
121	
122	test("a non-integer index is reported rather than silently coerced", () => {
123	  const out = rule.run(ctxOf({
124	    "data/venues.json": LOOKUPS,
125	    "data/days/2026-08-07.json": [{ id: "X", title: "A", genre: "Comedy", venue: "33", room: 0, ts: 1 }],
126	  }));
127	  assert.equal(out.length, 1);
128	  assert.match(out[0].what, /genre is "Comedy", not an integer index/);
129	});
130	
131	test("no data layer in the tree ⇒ no findings (relevance-first)", () => {
132	  assert.deepEqual(rule.run(ctxOf({ "README.md": {} })), []);
133	});
134	
135	test("this repo's committed data satisfies the invariant", () => {
136	  // The live gate: every real day file plus the master, read off disk.
137	  const tree = ["data/venues.json", "data/normalized/shows.min.json"];
138	  const days = readFileSync(path.join(REPO, "data/days/index.json"), "utf8");
139	  for (const d of JSON.parse(days).dates) tree.push(`data/days/${d}.json`);
140	  const present = tree.filter((f) => existsSync(path.join(REPO, f)));
141	  assert.ok(present.length > 2, "expected the committed day files to be present");
142	
143	  const out = rule.run({
144	    files: present,
145	    read: (p) => (present.includes(p) ? readFileSync(path.join(REPO, p), "utf8") : null),
146	  });
147	  assert.deepEqual(out, [], `committed data violates the lookup-index contract:\n${
148	    out.map((f) => `${f.file}: ${f.what}`).join("\n")}`);
149	});
150	
151	// --- normalizer-selftest-in-verify: the one offline transform check must stay
152	// wired into scripts/verify.sh ---
153	
154	const NORMALIZER_PY = `import sys\nif "--selftest" in sys.argv:\n    run_selftest()\n`;
155	
156	const verifyWithSelftest = `#!/usr/bin/env bash
157	set -euo pipefail
158	
159	step "Normalizer self-test — normalize.py --selftest"
160	if command -v python3 >/dev/null 2>&1; then
161	  python3 scraper/normalize.py --selftest
162	fi
163	`;
164	
165	// The label survives; the invocation is gone. A grep for the two tokens passes
166	// here — which is precisely why the check strips `step "..."` before looking.
167	const verifyLabelOnly = `#!/usr/bin/env bash
168	set -euo pipefail
169	
170	step "Normalizer self-test — normalize.py --selftest"
171	echo "skipped"
172	`;
173	
174	test("verify.sh invoking the self-test ⇒ no findings", () => {
175	  const out = selftestRule.run(textCtx({
176	    "scraper/normalize.py": NORMALIZER_PY,
177	    "scripts/verify.sh": verifyWithSelftest,
178	  }));
179	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
180	});
181	
182	test("a verify.sh left with only the step label is reported", () => {
183	  // The exact regression this guards: the step is gutted, the heading stays, and
184	  // the only offline verification a scraper change can get silently disappears.
185	  const out = selftestRule.run(textCtx({
186	    "scraper/normalize.py": NORMALIZER_PY,
187	    "scripts/verify.sh": verifyLabelOnly,
188	  }));
189	  assert.equal(out.length, 1);
190	  assert.equal(out[0].rule, "edfringe-normalizer-selftest-in-verify");
191	  assert.equal(out[0].severity, "blocking");
192	  assert.equal(out[0].file, "scripts/verify.sh");
193	  assert.match(out[0].what, /never invokes it/);
194	  assert.ok(out[0].fix.includes("--selftest"), "the fix must name the command to restore");
195	});
196	
197	test("a commented-out invocation does not count as wired", () => {
198	  const out = selftestRule.run(textCtx({
199	    "scraper/normalize.py": NORMALIZER_PY,
200	    "scripts/verify.sh": `#!/usr/bin/env bash\n# python3 scraper/normalize.py --selftest\necho hi\n`,
201	  }));
202	  assert.equal(out.length, 1);
203	});
204	
205	test("a trailing comment naming the command does not count as wired", () => {
206	  const out = selftestRule.run(textCtx({
207	    "scraper/normalize.py": NORMALIZER_PY,
208	    "scripts/verify.sh": `#!/usr/bin/env bash\nnode --check js/app.js  # unlike normalize.py --selftest, this is syntax only\n`,
209	  }));
210	  assert.equal(out.length, 1);
211	});
212	
213	test("a normalizer with no --selftest to run ⇒ no findings (relevance-first)", () => {
214	  assert.deepEqual(selftestRule.run(textCtx({
215	    "scraper/normalize.py": "def main():\n    pass\n",
216	    "scripts/verify.sh": verifyLabelOnly,
217	  })), []);
218	});
219	
220	test("no normalizer or no verify.sh in the tree ⇒ no findings (relevance-first)", () => {
221	  assert.deepEqual(selftestRule.run(textCtx({ "scripts/verify.sh": verifyLabelOnly })), []);
222	  assert.deepEqual(selftestRule.run(textCtx({ "scraper/normalize.py": NORMALIZER_PY })), []);
223	});
224	
225	test("this repo's verify.sh still runs the normalizer self-test", () => {
226	  // The live gate: the real script and the real normalizer, read off disk.
227	  const { present, ctx } = diskCtx(["scraper/normalize.py", "scripts/verify.sh"]);
228	  assert.equal(present.length, 2, "expected both files to be present");
229	  const out = selftestRule.run(ctx);
230	  assert.deepEqual(out, [], `the offline transform check has fallen out of the gate:\n${
231	    out.map((f) => f.what).join("\n")}`);
232	});
233	
234	// --- data-dir-is-generator-output: every committed file under data/ must be
235	// something scraper/normalize.py produces ---
236	
237	const cleanDataTree = {
238	  "data/venues.json": "",
239	  "data/shows.json": "",
240	  "data/normalized/shows.json": "",
241	  "data/normalized/shows.min.json": "",
242	  "data/normalized/descriptions.min.json": "",
243	  "data/days/index.json": "",
244	  "data/days/2026-08-07.json": "",
245	  "js/app.js": "",
246	};
247	
248	test("a data/ holding only normalizer output ⇒ no findings", () => {
249	  const out = dataDirRule.run(textCtx(cleanDataTree));
250	  assert.deepEqual(out, [], `expected no findings, got ${JSON.stringify(out, null, 2)}`);
251	});
252	
253	test("the named scraper input data/prices.json is allowed; a lookalike is not", () => {
254	  // prices.json is the one committed file under data/ that normalize.py READS
255	  // rather than writes (scraper/fetch_prices.py produces it). It is allowed by
256	  // name, so a second file cannot ride in on its shape.
257	  assert.deepEqual(dataDirRule.run(textCtx({ ...cleanDataTree, "data/prices.json": "" })), []);
258	  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/prices.backup.json": "" }));
259	  assert.equal(out.length, 1);
260	  assert.equal(out[0].file, "data/prices.backup.json");
261	  assert.ok(out[0].fix.includes("data/prices.json"),
262	    "the fix must name the inputs that ARE allowed, so the reader can tell the two apart");
263	});
264	
265	test("a probe's output committed under data/ is reported", () => {
266	  // The exact regression this guards: a throwaway probe's answer is parked in
267	  // data/ as if it were data, where nothing regenerates it and the next
268	  // refresh-shows run neither maintains nor removes it.
269	  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/ticket-status-enum.json": "" }));
270	  assert.equal(out.length, 1);
271	  assert.equal(out[0].rule, "edfringe-data-dir-is-generator-output");
272	  assert.equal(out[0].severity, "blocking");
273	  assert.equal(out[0].file, "data/ticket-status-enum.json");
274	  assert.match(out[0].what, /is not something scraper\/normalize\.py produces/);
275	  assert.ok(out[0].fix.includes("normalize.py"), "the fix must name the producer to fix instead");
276	});
277	
278	test("a force-added raw scrape cache file gets its own un-track fix", () => {
279	  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/raw_pages/events_1.json": "" }));
280	  assert.equal(out.length, 1);
281	  assert.equal(out[0].file, "data/raw_pages/events_1.json");
282	  assert.match(out[0].fix, /git rm --cached data\/raw_pages\/events_1\.json/);
283	});
284	
285	test("a hand-written note dropped beside the normalized files is reported", () => {
286	  const out = dataDirRule.run(textCtx({ ...cleanDataTree, "data/normalized/NOTES.md": "" }));
287	  assert.equal(out.length, 1);
288	  assert.equal(out[0].file, "data/normalized/NOTES.md");
289	});
290	
291	test("a whole new output directory is reported, per file, sorted", () => {
292	  const out = dataDirRule.run(textCtx({
293	    ...cleanDataTree,
294	    "data/weeks/2026-w32.json": "",
295	    "data/hand/notes.json": "",
296	  }));
297	  assert.equal(out.length, 2);
298	  assert.deepEqual(out.map((f) => f.file), ["data/hand/notes.json", "data/weeks/2026-w32.json"]);
299	});
300	
301	test("no data/ in the tree ⇒ no findings (relevance-first)", () => {
302	  assert.deepEqual(dataDirRule.run(textCtx({ "README.md": "hi", "scraper/normalize.py": "" })), []);
303	});
304	
305	test("this repo's committed data/ holds only generator output", () => {
306	  // The live gate: every tracked file, read straight from git.
307	  const files = execFileSync("git", ["ls-files"], { cwd: REPO, encoding: "utf8" }).split("\n").filter(Boolean);
308	  const out = dataDirRule.run({ files, read: () => null });
309	  assert.deepEqual(out, [], `data/ holds something the normalizer does not produce:\n${
310	    out.map((f) => `${f.file}: ${f.what}`).join("\n")}`);
311	});
312	
313	test("the pack manifest declares the checks and stays hand-declared", () => {
314	  assert.equal(pack.id, "edfringe-data");
315	  assert.equal(pack.detect, null, "a local pack is never fingerprinted");
316	  assert.equal(pack.marker, null);
317	  assert.equal(pack.prose, "RULES.md");
318	  assert.ok(pack.worldRules.includes(rule), "the check must be listed on the manifest or it never runs");
319	  assert.ok(pack.worldRules.includes(selftestRule), "the check must be listed on the manifest or it never runs");
320	  assert.ok(pack.worldRules.includes(dataDirRule), "the check must be listed on the manifest or it never runs");
321	  assert.ok(existsSync(path.join(__dirname, "RULES.md")));
322	});
